{
  "targetChapterCount": 100,
  "volumeCount": 3,
  "openQuestions": [
    {
      "id": "oq_01",
      "question": "界门外侧寂灭死渊中是否潜藏着具有主宰意志的域外古魔实体？",
      "blocking": false,
      "status": "deferred"
    },
    {
      "id": "oq_02",
      "question": "苏凌霜在第三卷天武城决战时是否需要引动太清仙宗禁忌底蕴以身殉阵破局？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "oq_03",
      "question": "大乾老皇主是否在赵玄极身后秘密操控九鼎皇天大阵以求夺舍还魂？",
      "blocking": false,
      "status": "open"
    },
    {
      "id": "baseline-content-review",
      "question": "三卷1–32、33–66、67–100基线已同步；卷二覆盖北航和入渊前置。关系阶段、航路与等级解释已补充，但寿元、法宝、终局代价、配角认知和正文返修未通过，不能批准写作。",
      "blocking": true,
      "status": "open"
    }
  ],
  "dependencies": [
    {
      "id": "dep_01",
      "targetId": "ms_vol1_turn",
      "fact": {
        "eventType": "plot_progress",
        "subjectId": "chapter-1",
        "predicate": "status",
        "equals": {
          "status": "realized"
        }
      },
      "requiredness": "must",
      "description": "林辰必须在濒死死斗中初次成功催动乾坤逆命真解以寿换力，方能在外门大比中逆斩暗桩并震慑宗门高层。"
    },
    {
      "id": "dep_02",
      "targetId": "ms_vol1_climax",
      "sourceId": "ms_vol1_turn",
      "requiredness": "must",
      "description": "林辰必须先与苏凌霜结成盟约并夺得古境准入符牌，方能进入灵虚古境核心祭坛阻截墨幽屠。"
    },
    {
      "id": "dep_03",
      "targetId": "ms_vol2_turn",
      "sourceId": "ms_vol1_climax",
      "requiredness": "must",
      "description": "林辰必须在斩杀墨幽屠后因白发早衰和皇朝追杀登舟南渡，才能在赤霄大陆太微天宝城遭遇商盟暗算并揭破暗盟。"
    },
    {
      "id": "dep_04",
      "targetId": "ms_vol2_climax",
      "sourceId": "ms_vol2_turn",
      "requiredness": "must",
      "description": "林辰必须先掌握跨陆密约与地脉毒火走势，才能准确杀入赤霄天坑斩杀炎煞尊者并抢夺神火髓与界门残印。"
    },
    {
      "id": "dep_05",
      "targetId": "ms_vol3_turn",
      "sourceId": "ms_vol2_boundary",
      "requiredness": "must",
      "description": "必须先完成北境断链和界渊入口条件，才能在第三卷深入界渊取得第三残片、合成完整钥匙。"
    },
    {
      "id": "dep_06",
      "targetId": "ms_vol3_climax",
      "sourceId": "ms_vol3_turn",
      "requiredness": "must",
      "description": "林辰必须先在苍冥界渊彻底参透空间秩序并集齐三印，方有实力杀回天武城正面硬撼赵玄极的九鼎皇天大阵。"
    },
    {
      "id": "dep_07",
      "targetId": "ms_book_payoff",
      "sourceId": "ms_vol3_climax",
      "requiredness": "must",
      "description": "必须先彻底诛杀赵玄极并斩断六道转轮偷命策阵眼，天地万民命寿方能归位，补天定界大功德反哺方可兑现。"
    },
    {
      "id": "dep_north_passage",
      "targetId": "ms_vol2_boundary",
      "sourceId": "ms_vol2_climax",
      "requiredness": "must",
      "description": "赤霄夺印、北航与结盟先于北境断链；不能从天坑直接跳到界渊合匙。"
    }
  ]
}

{
  "coreConflict": "主角以自身寿命换取暴烈战力求存求真，与大乾皇朝及魔道巨擘妄图血祭诸域生灵命寿强破界门的霸权行径爆发死生冲突。",
  "endingDirection": "主角逆转命寿通灵之厄，彻底粉碎大乾九鼎窃寿大阵并斩灭域外寂灭侵蚀，以破虚极境与补天圣法重铸三大陆界门守恒平衡。",
  "unresolvedQuestions": [
    {
      "id": "uq_03",
      "question": "三大陆界门开启时是否会触发天地灵气守恒律的反向大吞噬？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_04",
      "question": "大乾天朝皇室命修是否秘密掌握借国运转移燃寿反噬之法？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_06",
      "question": "主角以命寿换力突破至归一境时，延寿灵泉能否中和其肉身永久衰老的暗伤？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_08",
      "question": "太古界门破虚匙共有几柄，补天阁内部是否封存有另外的钥匙残片？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "uq_09",
      "question": "十年前青玄极天界门的无故灵震是否由主角家族或某位通天境强者的秘密燃寿破门引发？",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "audit-scene-31",
      "question": "第31章已绑定无尽虚海商路 loc_21；跨大陆海域不挂在青玄大陆之下。航程天数仍随时间线统一核查。",
      "blocking": false,
      "status": "resolved"
    },
    {
      "id": "audit-volume-timeline",
      "question": "批准章纲以32/66/100为卷界，正文第30、53、66章出现不同收卷描述；第99–100章第五十日又写数十载/十载经历。须统一时间线与分卷。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-artifact-continuity",
      "question": "第73章三枚破虚匙已合拢，98章又以三枚散落残片重组；缺少中间状态转换与新代价说明。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-ending-cost",
      "question": "第99章写“再无折寿枯竭之患”，以天道奖励取消逆命代价，与命寿通灵律消耗不可逆冲突；结尾必须说明能量来源、使用上限与持续代价，并逐章复核第98–100章。",
      "blocking": true,
      "status": "open"
    },
    {
      "id": "audit-relationship-stages",
      "question": "rel_01与rel_05已拆分阶段，但仍须对照逐章事件验证；另四条关系、配角独立行动和秘密认知边界尚待补全。",
      "blocking": true,
      "status": "open"
    }
  ]
}

